<?php /** One modifier row. Data: m, tz */ $id = (int) $m['modifier_id']; $undecided = $m['recipe_id'] === null && $m['action'] === 'none'; $unmapped = $m['recipe_id'] === null && $m['action'] !== 'none'; $c = MODIFIER_ACTION_COLOR[$m['action']] ?? 'secondary'; ?>
<tr id="modifier-row-<?= $id ?>" class="<?= $unmapped || $undecided ? 'table-warning' : '' ?>"><td><code><?= e($m['code']) ?></code></td><td><?= e($m['name']) ?></td><td><span class="badge bg-soft-light text-dark border"><?= e($m['source_name'] ?? 'typed') ?></span></td>
    <td><?php if ($undecided): ?><span class="badge bg-soft-warning text-warning">undecided</span><?php else: ?><span class="badge bg-soft-<?= $c ?> text-<?= $c ?>"><?= e($m['action']) ?></span><?php endif; ?></td>
    <td><?= $m['recipe_id'] !== null ? hx_link('/recipes/' . (int) $m['recipe_id'], e($m['recipe_name'])) : '<span class="text-muted">—</span>' ?><?= (int) $m['per_item'] > 0 ? ' <span class="fs-11 text-muted">+' . (int) $m['per_item'] . ' per item</span>' : '' ?></td>
    <td class="text-end"><?= e(ri_fmt($m['qty_factor'], 2)) ?></td><td class="fs-12 text-muted"><?= e(format_ts($m['first_seen_at'], $tz, 'M j')) ?></td>
    <td class="text-end"><?= hx_link(with_back('/modifiers/' . $id . '/map', here_url()), 'Map', 'btn btn-sm ' . ($unmapped || $undecided ? 'btn-warning' : 'btn-light'), 'id="modifier-row-' . $id . '-map"') ?></td></tr>
